import csv, re, datetime
from collections import Counter

with open('dataset/employees.csv') as f:
    emps = list(csv.DictReader(f))
peselset = {e['PESEL'] for e in emps}
with open('dataset/tasks.csv') as f:
    taskpay = {int(t['task_id']): int(t['pay_per_completion']) for t in csv.DictReader(f)}
with open('dataset/timesheet.csv') as f:
    ts = list(csv.DictReader(f))

def parse(d):
    try: return datetime.date.fromisoformat(d)
    except ValueError: return None

types = Counter(); rows_by_combo = {}
for r in ts:
    flags = []
    if parse(r['date']) is None: flags.append('bad_date')
    if r['employee_id'] not in peselset: flags.append('bad_emp')
    if not re.fullmatch(r'\[\s*(\d+\s*(,\s*\d+\s*)*)?\]', r['performed_tasks']): flags.append('bad_fmt')
    tl = [int(t) for t in re.findall(r'\d+', r['performed_tasks'])]
    if any(t not in taskpay for t in tl): flags.append('unk_task')
    known = sum(taskpay[t] for t in tl if t in taskpay)
    if abs(known - float(r['bonus'])) > 0.01: flags.append('bonus_mismatch')
    if float(r['bonus']) < 0: flags.append('neg_bonus')
    combo = tuple(flags)
    types[combo] += 1
    rows_by_combo.setdefault(combo, []).append(r['id'])

for combo, n in sorted(types.items(), key=lambda kv: -kv[1]):
    print(n, combo, (rows_by_combo[combo][:5] if combo else ''))
