"""Cleaning Service — total monthly salaries per employee.

Salary per billing month = (total hours worked in the period x hourly rate)
                         + sum of pay_per_completion for valid completed tasks.

Billing periods are monthly, each starting on the first Tuesday of the
calendar month (Tuesday is the weekday of the dataset's earliest record,
2025-03-04, which is the first Tuesday of March 2025; the data ends
2025-06-30, the day before the first Tuesday of July 2025).

Data repairs applied:
- employee_id values failing the PESEL checksum are mapped to the unique
  employee PESEL that is an exact digit-anagram (and nearest by Hamming
  distance); if no unambiguous match exists the row is dropped.
- Impossible dates (day overflowing the month, e.g. 2025-06-31) are clamped
  to the last real day of the stated month.
- Malformed performed_tasks lists (missing brackets) are parsed by
  extracting the digit groups, which are intact.
- Task ids absent from tasks.csv are unidentifiable noise and are excluded
  from the bonus.
- The timesheet's salary_amount and bonus columns are derived values
  (inconsistent/noisy on corrupted rows) and are not used; the bonus is
  recomputed from tasks.csv.
"""
import csv
import datetime
import math
import re

DATA_DIR = "/app/dataset"


def pesel_valid(p: str) -> bool:
    if len(p) != 11 or not p.isdigit():
        return False
    weights = [1, 3, 7, 9, 1, 3, 7, 9, 1, 3]
    s = sum(int(d) * w for d, w in zip(p[:10], weights))
    return (10 - s % 10) % 10 == int(p[10])


def load_employees() -> dict[str, float]:
    with open(f"{DATA_DIR}/employees.csv", newline="", encoding="utf-8") as f:
        return {row["PESEL"]: float(row["hourly_rate"])
                for row in csv.DictReader(f)}


def load_task_pay() -> dict[int, int]:
    with open(f"{DATA_DIR}/tasks.csv", newline="", encoding="utf-8") as f:
        return {int(row["task_id"]): int(float(row["pay_per_completion"]))
                for row in csv.DictReader(f)}


def resolve_employee(emp_id: str, pesels: list[str]) -> str | None:
    """Return the matching employee PESEL, repairing corrupted ids."""
    if emp_id in pesels:
        return emp_id
    if len(emp_id) != 11 or not emp_id.isdigit():
        return None
    # Corrupted ids are digit permutations of a real PESEL; require a
    # unique anagram match to accept the repair.
    candidates = [p for p in pesels if sorted(p) == sorted(emp_id)]
    if len(candidates) == 1:
        return candidates[0]
    return None


def parse_date(raw: str) -> datetime.date | None:
    """Parse a date, clamping an overflowing day to the month's last day."""
    try:
        return datetime.date.fromisoformat(raw)
    except ValueError:
        pass
    m = re.fullmatch(r"(\d{4})-(\d{2})-(\d{2})", raw)
    if not m:
        return None
    year, month, day = int(m[1]), int(m[2]), int(m[3])
    if not 1 <= month <= 12:
        return None
    next_month = datetime.date(year + month // 12, month % 12 + 1, 1)
    last_day = (next_month - datetime.timedelta(days=1)).day
    try:
        return datetime.date(year, month, min(day, last_day))
    except ValueError:
        return None


def first_tuesday(year: int, month: int) -> datetime.date:
    d = datetime.date(year, month, 1)
    return d + datetime.timedelta(days=(1 - d.weekday()) % 7)


def billing_month(d: datetime.date) -> tuple[int, int]:
    """Billing periods run from the first Tuesday of a month up to the day
    before the first Tuesday of the next month."""
    if d >= first_tuesday(d.year, d.month):
        return d.year, d.month
    prev = datetime.date(d.year, d.month, 1) - datetime.timedelta(days=1)
    return prev.year, prev.month


def answer() -> dict[str, list[int]]:
    rates = load_employees()
    task_pay = load_task_pay()
    pesels = list(rates)

    totals: dict[str, dict[tuple[int, int], float]] = {p: {} for p in pesels}

    with open(f"{DATA_DIR}/timesheet.csv", newline="", encoding="utf-8") as f:
        for row in csv.DictReader(f):
            emp = resolve_employee(row["employee_id"].strip(), pesels)
            if emp is None:
                continue
            date = parse_date(row["date"].strip())
            if date is None:
                continue
            try:
                hours = float(row["hours_worked"])
            except ValueError:
                continue
            if hours < 0:
                continue
            tasks = [int(t) for t in re.findall(r"\d+", row["performed_tasks"])]
            bonus = sum(task_pay[t] for t in tasks if t in task_pay)
            period = billing_month(date)
            month_totals = totals[emp]
            month_totals[period] = (month_totals.get(period, 0.0)
                                    + hours * rates[emp] + bonus)

    result: dict[str, list[int]] = {}
    for pesel, month_totals in totals.items():
        result[pesel] = [int(math.floor(month_totals[period] + 0.5))
                         for period in sorted(month_totals)]
    return result


if __name__ == "__main__":
    import json
    with open("/app/answer.json", "w") as f:
        json.dump(answer(), f, default=list)

